using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
public sealed class NoticeState {public string key="";public bool read;public long snoozeUntil;}
public sealed class SpaceNotice {public string key="",kind="",target="",title="",detail="",created="";}
internal static class NotificationCenter {
 internal static void Validate(Data d){if(d.noticeStates==null)d.noticeStates=new List<NoticeState>();if(d.notices==null)d.notices=new List<SpaceNotice>();if(d.noticeStates.Count>1000||d.notices.Count>100)throw new InvalidDataException("Trop de notifications enregistrées.");if(d.noticeStates.Any(s=>s==null||String.IsNullOrWhiteSpace(s.key)||s.key.Length>500||s.snoozeUntil<0||s.snoozeUntil>DateTime.MaxValue.Ticks)||d.noticeStates.Select(s=>s.key).Distinct().Count()!=d.noticeStates.Count)throw new InvalidDataException("État de notification invalide.");if(d.notices.Any(n=>n==null||String.IsNullOrWhiteSpace(n.key)||n.key.Length>500||(n.title??"").Length>500||(n.detail??"").Length>4000||!new[]{"backup","update","save"}.Contains(n.kind))||d.notices.Select(n=>n.key).Distinct().Count()!=d.notices.Count)throw new InvalidDataException("Notification invalide.");}
 internal static void Incident(Data d,string kind,string key,string title,string detail){key=kind+"/"+key;if(d.notices.Any(n=>n.key==key))return;d.notices.Add(new SpaceNotice{key=key,kind=kind,title=title,detail=(detail??"").Substring(0,Math.Min(4000,(detail??"").Length)),created=DateTime.Now.ToString("s")});while(d.notices.Count>100)d.notices.RemoveAt(0);}
 internal static List<SpaceNotice> Current(Data d,DateTime now){
  var list=new List<SpaceNotice>();string today=now.ToString("yyyy-MM-dd");
  foreach(var t in d.tasks.Where(t=>t.status!="done"&&!String.IsNullOrEmpty(t.due))){var at=Schedule.At(t.due,t.dueTime);var trigger=t.remindMinutes>=0?at.AddMinutes(-t.remindMinutes):at.Date;if(now>=trigger)list.Add(new SpaceNotice{key="task/"+t.id+"/"+t.due+"/"+t.dueTime,kind="task",target=t.id,title=t.title,detail=(at.Date<now.Date?"En retard":"À faire")+" · "+at.ToString("dd/MM HH:mm")+" · "+t.project});}
  foreach(var e in d.events){var at=Schedule.At(e.date,e.time);if(now>=at.AddMinutes(-Math.Max(0,e.remindMinutes))&&now<=at.AddMinutes(e.duration))list.Add(new SpaceNotice{key="event/"+e.id+"/"+e.date+"/"+e.time,kind="event",target=e.id,title=e.title,detail="Rendez-vous · "+at.ToString("dd/MM HH:mm")});}
  var b=d.budget;if(b.hasBalance){long balance=Finance.Balance(b,now);if(balance<0)list.Add(new SpaceNotice{key="balance/"+today,kind="budget",title=Finance.ExceedsOverdraft(b,balance)?"Découvert autorisé dépassé":"Votre solde est négatif",detail="Solde saisi et opérations enregistrées · "+Finance.Money(balance)});var forecast=Finance.Forecast(b,now,new DateTime(now.Year,now.Month,DateTime.DaysInMonth(now.Year,now.Month)));if(Finance.ExceedsOverdraft(b,forecast.Minimum)&&!Finance.ExceedsOverdraft(b,balance))list.Add(new SpaceNotice{key="forecast/"+today,kind="budget",title="Découvert à surveiller",detail="Prévision minimale · "+Finance.Money(forecast.Minimum)+" le "+forecast.MinimumDate.ToString("dd/MM")});}
  foreach(var cap in b.caps){long spent=Finance.Spent(b,now,cap.category);if(spent>=cap.cents)list.Add(new SpaceNotice{key="cap/"+now.ToString("yyyy-MM")+"/"+cap.category,kind="budget",title="Budget atteint · "+cap.category,detail=Finance.Money(spent)+" / "+Finance.Money(cap.cents)});}
  if(b.reminders.enabled)foreach(var o in Finance.Pending(b,now.Date,now.Date.AddDays(b.reminders.daysBefore)).Where(o=>o.Rule.remind&&(o.Rule.kind=="expense"||b.reminders.includeIncome)&&o.Rule.cents>=b.reminders.minimumCents))list.Add(new SpaceNotice{key="budget/"+o.Key,kind="budget",title=o.Rule.title,detail="Échéance · "+o.Date.ToString("dd/MM")+" · "+Finance.Money(o.Rule.cents)});
  list.AddRange(d.notices.Where(n=>n.kind!="update"||NewerUpdate(n.key)).Reverse());return list;
 }
 static bool NewerUpdate(string key){Version version;return key.StartsWith("update/",StringComparison.Ordinal)&&Version.TryParse(key.Substring(7),out version)&&version>System.Reflection.Assembly.GetExecutingAssembly().GetName().Version;}
 internal static bool Unread(Data d,SpaceNotice n,DateTime utc){var s=d.noticeStates.FirstOrDefault(v=>v.key==n.key);return s==null||(!s.read&&s.snoozeUntil<=utc.ToUniversalTime().Ticks);}
 internal static void Set(Data d,string key,bool read,DateTime? snooze){var state=d.noticeStates.FirstOrDefault(s=>s.key==key);if(state==null){state=new NoticeState{key=key};d.noticeStates.Add(state);}state.read=read;state.snoozeUntil=snooze.HasValue?snooze.Value.ToUniversalTime().Ticks:0;while(d.noticeStates.Count>1000)d.noticeStates.RemoveAt(0);}
 internal static void Test(string folder){var st=new Store(Path.Combine(folder,"notifications"));var d=st.Value;var now=new DateTime(2028,5,3,10,0,0);d.tasks.Add(new WorkTask{id="n",title="Tâche",project="Personnel",status="todo",priority="Normale",due="2028-05-03"});var n=Current(d,now).Single();Set(d,n.key,false,now.ToUniversalTime().AddHours(1));if(Unread(d,n,now.ToUniversalTime())||!Unread(d,n,now.ToUniversalTime().AddHours(2)))throw new Exception("Report notification");Set(d,n.key,true,null);st.Save();d=new Store(st.Root).Value;if(Unread(d,n,now.ToUniversalTime()))throw new Exception("Lecture persistante");d.tasks[0].status="done";if(Current(d,now).Count!=0)throw new Exception("Notification résolue");Incident(d,"backup","one","Échec","Erreur");Incident(d,"backup","one","Échec","Erreur");if(Current(d,now).Count!=1)throw new Exception("Incident dupliqué");d.budget.caps.Add(new BudgetCap{category="Courses",cents=100});d.budget.entries.Add(new BudgetEntry{id="expense",title="Courses",date="2028-05-03",kind="expense",category="Courses",cents=150});d.budget.hasBalance=true;d.budget.balanceDate="2028-05-03";d.budget.balanceCents=-1000;d.budget.overdraftKnown=true;d.budget.overdraftCents=500;if(!Current(d,now).Any(x=>x.title=="Découvert autorisé dépassé")||!Current(d,now).Any(x=>x.title=="Budget atteint · Courses"))throw new Exception("Alertes budget");d.events.Add(new CalendarEvent{id="event",title="RDV",date="2028-05-03",time="10:00",duration=30,remindMinutes=15});if(!Current(d,now).Any(x=>x.kind=="event")||Current(d,now.AddHours(1)).Any(x=>x.kind=="event"))throw new Exception("Expiration rendez-vous");File.WriteAllText(Path.Combine(folder,"NOTIFICATIONS_PASS.txt"),"PASS: due task, snooze, read persistence, resolution, incident deduplication.");}
}
internal sealed partial class ModernWorkspace {
 Button noticeButton;bool noticeAll;int noticeCount=-1;
 void InstallNoticeButton(StackPanel chrome){noticeButton=Btn("",delegate{Go("Notifications");},false,true);noticeButton.ToolTip="Centre de notifications";chrome.Children.Insert(0,noticeButton);RefreshNoticeBadge();}
 internal void RefreshNoticeBadge(bool refreshPage=true){if(noticeButton==null)return;int count=store.Value.settings.PrivacyMode?0:NotificationCenter.Current(store.Value,DateTime.Now).Count(n=>NotificationCenter.Unread(store.Value,n,DateTime.UtcNow));var line=new StackPanel{Orientation=Orientation.Horizontal};line.Children.Add(LineIcon("Notifications",Muted));line.Children.Add(T(count==0?"Notifications":count+"",11,Muted));noticeButton.Content=line;noticeButton.Visibility=store.Value.settings.PrivacyMode?Visibility.Collapsed:Visibility.Visible;bool changed=noticeCount!=count;noticeCount=count;if(refreshPage&&changed&&selected=="Notifications"&&!store.Value.settings.PrivacyMode)Refresh();}
 void NoticeChange(Action action){try{PersonalWorkflows.Change(store,action);}catch(Exception ex){MessageBox.Show(ex.Message,"Notifications");}Refresh();}
 void NotificationsPage(StackPanel body){
  var notices=NotificationCenter.Current(store.Value,DateTime.Now);var tools=new WrapPanel{Margin=new Thickness(0,0,0,18)};tools.Children.Add(Btn("À lire",delegate{noticeAll=false;Refresh();},!noticeAll));tools.Children.Add(Btn("Toutes les actives",delegate{noticeAll=true;Refresh();},noticeAll));tools.Children.Add(Btn("Tout marquer comme lu",delegate{NoticeChange(delegate{foreach(var n in notices)NotificationCenter.Set(store.Value,n.key,true,null);});},false,true));body.Children.Add(tools);body.Children.Add(T("Les échéances résolues disparaissent automatiquement. Les incidents restent consultables jusqu’à leur retrait.",12,Muted,new Thickness(0,0,0,18)));
  var visible=notices.Where(n=>noticeAll||NotificationCenter.Unread(store.Value,n,DateTime.UtcNow)).ToList();if(visible.Count>200)body.Children.Add(T("Affichage des 200 premières alertes sur "+visible.Count+". Utilisez « Tout marquer comme lu » pour vider la liste.",11,Muted));if(visible.Count==0)body.Children.Add(T("Tout est à jour. Vous pouvez avancer tranquillement.",18));
  foreach(var item in visible.Take(200)){var n=item;var content=new StackPanel();content.Children.Add(T(n.detail,12,Muted,new Thickness(0,0,0,12)));var state=store.Value.noticeStates.FirstOrDefault(s=>s.key==n.key);if(state!=null&&state.snoozeUntil>DateTime.UtcNow.Ticks)content.Children.Add(T("Reportée jusqu’au "+new DateTime(state.snoozeUntil,DateTimeKind.Utc).ToLocalTime().ToString("dd/MM HH:mm"),11,Accent));var actions=new WrapPanel();actions.Children.Add(Btn("Ouvrir",delegate{OpenNotice(n);},true));actions.Children.Add(Btn(state!=null&&state.read?"Marquer à lire":"Marquer comme lu",delegate{NoticeChange(()=>NotificationCenter.Set(store.Value,n.key,!(state!=null&&state.read),null));},false,true));var menu=new ContextMenu();foreach(int minutes in new[]{15,60,1440}){int delay=minutes;var option=new MenuItem{Header=delay==15?"Dans 15 minutes":delay==60?"Dans une heure":"Dans 24 heures"};option.Click+=delegate{NoticeChange(()=>NotificationCenter.Set(store.Value,n.key,false,DateTime.UtcNow.AddMinutes(delay)));};menu.Items.Add(option);}Button snooze=null;snooze=Btn("Reporter ⌄",delegate{menu.PlacementTarget=snooze;menu.IsOpen=true;},false,true);snooze.ContextMenu=menu;actions.Children.Add(snooze);if(new[]{"backup","save","update"}.Contains(n.kind))actions.Children.Add(Btn("Retirer",delegate{NoticeChange(()=>{store.Value.notices.RemoveAll(v=>v.key==n.key);store.Value.noticeStates.RemoveAll(v=>v.key==n.key);});},false,true));content.Children.Add(actions);var card=Card(n.title,content);card.Margin=new Thickness(0,0,0,14);body.Children.Add(card);}
 }
 void OpenNotice(SpaceNotice n){if(n.kind=="task"){var t=store.Value.tasks.FirstOrDefault(v=>v.id==n.target);if(t!=null)owner.Edit(t);}else if(n.kind=="event"){var e=store.Value.events.FirstOrDefault(v=>v.id==n.target);if(e!=null)EditAppointment(e,Schedule.Day(e.date));}else Go(n.kind=="budget"?"Mon budget":n.kind=="update"?"Mises à jour":"Réglages");}
}
